import React, { useEffect, useState } from "react";
import api from "@landinghub/api"; // hoặc import axios nếu bạn chưa có module này
import "../styles/MyLibrary.css";

const MyLibrary = () => {
  const [landings, setLandings] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const userId = localStorage.getItem("userId");
    if (!userId) {
      console.error("❌ Không tìm thấy userId trong localStorage");
      setLoading(false);
      return;
    }

    // ✅ Gọi đúng API backend
    api
      .get(`/landing/my/${userId}`)
      .then((res) => {
        console.log("✅ API trả về:", res.data);
        setLandings(res.data);
      })
      .catch((err) => {
        console.error("❌ Lỗi khi load MyLibrary:", err);
      })
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <p>Đang tải...</p>;

  // ✅ Kiểm tra rỗng đúng cách
  if (!landings || landings.length === 0) {
    return (
      <div className="no-landing">
        <h2>Kho Landing Page của tôi</h2>
        <p>Chưa có landing nào được lưu.</p>
      </div>
    );
  }

  return (
    <div className="mylibrary">
      <h2>Kho Landing Page của tôi</h2>
      <div className="landing-list">
        {landings.map((item) => (
          <div key={item._id} className="landing-card">
            <img
              src={item.thumbnail || "/default-thumbnail.jpg"}
              alt={item.name}
              className="thumbnail"
            />
            <h3>{item.name}</h3>
            <a
              href={item.landingPageUrl}
              target="_blank"
              rel="noopener noreferrer"
            >
              Xem landing
            </a>
          </div>
        ))}
      </div>
    </div>
  );
};

export default MyLibrary;
